package mdm

import (
	"fmt"
	"io"
	"strings"
	"text/template"

	"github.com/meetflowstate/flowstate-telemetry/internal/config"
	"github.com/meetflowstate/flowstate-telemetry/internal/shell"
)

const ansibleTemplate = `---
# Flowstate Telemetry — Ansible Playbook
# Generated by flowstate-telemetry generate-mdm --format ansible
# Usage: ansible-playbook flowstate-telemetry.yml -i inventory
#
# KEY: flowstate_key is ONE Flowstate key. Every host/user it configures is
# attributed to that key's owner in Flowstate; for per-user attribution set
# flowstate_key per host (host_vars) or per user.
#
# The key is never exported as OTEL_EXPORTER_OTLP_HEADERS (every OpenTelemetry
# SDK would send it to its own collector): it goes into each tool's own
# settings and ~/.config/flowstate-telemetry/env (mode 0600). The shell
# profile (~/.bashrc, and ~/.zshrc on macOS) reads it from there at start-up
# and Gemini CLI gets it from a "gemini" wrapper function; no profile stores
# the key. Settings files that hold the key are created 0600.
#
# Set flowstate_endpoint / flowstate_key (inventory, host_vars, --extra-vars)
# to override the defaults below. The defaults are !unsafe: Ansible never
# templates them, so a key containing "{{ "{{" }}" is used literally.

- name: Configure Flowstate AI Telemetry
  hosts: developers
  become: false
  vars:
    flowstate_default_endpoint: !unsafe {{ yq .Endpoint }}
    flowstate_default_key: !unsafe {{ yq .Key }}
    fs_endpoint: "{{ "{{ flowstate_endpoint | default(flowstate_default_endpoint) }}" }}"
    fs_key: "{{ "{{ flowstate_key | default(flowstate_default_key) }}" }}"
    # VS Code's user settings directory differs on macOS.
    fs_vscode_dir: "{{ "{{ ansible_env.HOME ~ ('/Library/Application Support/Code/User' if ansible_system == 'Darwin' else '/.config/Code/User') }}" }}"

  tasks:
    # A newline would split the env file and settings; quotes or shell
    # characters in the endpoint would reach the shell profile.
    - name: Check the Flowstate endpoint and key
      assert:
        that:
          - fs_endpoint is match('^https://[A-Za-z0-9._~:/%\[\]-]+$')
          - fs_key is not search('[\x00-\x1f\x7f]')
        fail_msg: "flowstate_endpoint must be an https URL (no quotes, spaces or shell characters) and flowstate_key may not contain control characters"
        quiet: true
      no_log: true

    - name: Remove the world-readable, process-wide variables written by earlier versions
      become: true
      lineinfile:
        path: /etc/environment
        regexp: "^{{ "{{ item }}" }}="
        state: absent
      loop:
        - FLOWSTATE_OTLP_ENDPOINT
        - FLOWSTATE_OTLP_KEY
        - OTEL_EXPORTER_OTLP_HEADERS

    - name: Remove the service.name override written by earlier versions
      become: true
      lineinfile:
        path: /etc/environment
        regexp: "^OTEL_RESOURCE_ATTRIBUTES=service.name=flowstate-telemetry$"
        state: absent

    - name: Ensure the Flowstate config directory exists (this user only)
      file:
        path: "{{ "{{ ansible_env.HOME }}" }}/.config/flowstate-telemetry"
        state: directory
        mode: "0700"

    - name: Write the endpoint and key for hook scripts and shells (mode 0600)
      copy:
        dest: "{{ "{{ ansible_env.HOME }}" }}/.config/flowstate-telemetry/env"
        content: |
          FLOWSTATE_OTLP_ENDPOINT={{ "{{ fs_endpoint }}" }}
          FLOWSTATE_OTLP_KEY={{ "{{ fs_key }}" }}
        mode: "0600"
      no_log: true

    - name: Ensure Claude Code config directory exists
      file:
        path: "{{ "{{ ansible_env.HOME }}" }}/.claude"
        state: directory
        mode: "0755"

    - name: Configure Claude Code telemetry
      copy:
        dest: "{{ "{{ ansible_env.HOME }}" }}/.claude/settings.json"
        content: |
          {
            "env": {
              "CLAUDE_CODE_ENABLE_TELEMETRY": "1",
              "OTEL_METRICS_EXPORTER": "otlp",
              "OTEL_LOGS_EXPORTER": "otlp",
              "OTEL_EXPORTER_OTLP_PROTOCOL": "http/protobuf",
              "OTEL_EXPORTER_OTLP_ENDPOINT": {{ "{{ fs_endpoint | to_json }}" }},
              "OTEL_EXPORTER_OTLP_HEADERS": {{ "{{ ('x-flowstate-key=' ~ fs_key) | to_json }}" }},
              "OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE": "delta",
              "OTEL_METRICS_INCLUDE_SESSION_ID": "true",
              "OTEL_METRICS_INCLUDE_ACCOUNT_UUID": "true"
            }
          }
        mode: "0600"
        force: false
      no_log: true
      when: ansible_env.HOME is defined

    - name: Check if VS Code settings directory exists
      stat:
        path: "{{ "{{ fs_vscode_dir }}" }}"
      register: vscode_dir

    - name: Configure VS Code Copilot Chat telemetry
      copy:
        dest: "{{ "{{ fs_vscode_dir }}" }}/settings.json"
        content: |
          {
            "github.copilot.chat.otel.enabled": true,
            "github.copilot.chat.otel.exporterType": "otlp-http",
            "github.copilot.chat.otel.otlpEndpoint": {{ "{{ fs_endpoint | to_json }}" }},
            "github.copilot.chat.otel.headers": { "x-flowstate-key": {{ "{{ fs_key | to_json }}" }} },
            "settingsSync.ignoredSettings": ["github.copilot.chat.otel.headers"]
          }
        mode: "0600"
        force: false
      no_log: true
      when: vscode_dir.stat.exists

    # Runs on the target host (a pipe lookup would run on the controller).
    - name: Check for Gemini CLI on the target
      shell: command -v gemini >/dev/null 2>&1 || test -d "$HOME/.gemini"
      register: gemini_check
      changed_when: false
      failed_when: false

    - name: Ensure Gemini config directory exists
      file:
        path: "{{ "{{ ansible_env.HOME }}" }}/.gemini"
        state: directory
        mode: "0755"
      when: gemini_check.rc == 0

    - name: Configure Gemini CLI telemetry
      copy:
        dest: "{{ "{{ ansible_env.HOME }}" }}/.gemini/settings.json"
        content: |
          {
            "telemetry": {
              "enabled": true,
              "target": "local",
              "otlpEndpoint": {{ "{{ fs_endpoint | to_json }}" }},
              "otlpProtocol": "http",
              "logPrompts": false
            }
          }
        mode: "0644"
        force: false
      when: gemini_check.rc == 0

    # ~/.bashrc everywhere, and ~/.zshrc on macOS (zsh is the default shell).
    # The block holds no key: it reads FLOWSTATE_OTLP_KEY from the env file.
    - name: Add the Flowstate shell profile block
      blockinfile:
        path: "{{ "{{ ansible_env.HOME }}/{{ item }}" }}"
        marker: "# {mark} Flowstate Telemetry"
        block: |
          export FLOWSTATE_OTLP_ENDPOINT={{ "{{ fs_endpoint | quote }}" }}
{{ range .ProfileLines }}          {{ . }}
{{ end }}        create: true
      loop: "{{ "{{ ['.bashrc', '.zshrc'] if ansible_system == 'Darwin' else ['.bashrc'] }}" }}"
`

// GenerateAnsible writes an Ansible playbook for Flowstate telemetry deployment.
func GenerateAnsible(w io.Writer, cfg config.Config) error {
	tmpl, err := template.New("ansible").Funcs(template.FuncMap{"yq": yamlQuote}).Parse(ansibleTemplate)
	if err != nil {
		return fmt.Errorf("parsing template: %w", err)
	}

	return tmpl.Execute(w, map[string]interface{}{
		"Endpoint":     cfg.Endpoint,
		"Key":          cfg.Key,
		"ProfileLines": profileLines(),
	})
}

// profileLines are the shell profile lines after FLOWSTATE_OTLP_ENDPOINT that
// the Ansible and Puppet artefacts write to ~/.bashrc (and ~/.zshrc on
// macOS): the key loader and the gemini wrapper. None holds the key, and
// none contains a single quote (Puppet embeds them single-quoted).
func profileLines() []string {
	return []string{
		"# FLOWSTATE_OTLP_KEY is read from ~/.config/flowstate-telemetry/env (mode 0600), not stored here.",
		shell.KeyLoader(""),
		"# Scopes the key and delta temporality to Gemini CLI only.",
		`function gemini { OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE=delta OTEL_EXPORTER_OTLP_HEADERS="x-flowstate-key=${FLOWSTATE_OTLP_KEY:-}" command gemini "$@"; }`,
	}
}

// yamlQuote renders s as a single-quoted YAML scalar (a quote is doubled;
// nothing else is special). Values with control characters are rejected
// before generation (config.Validate).
func yamlQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}
